from pathlib import Path
from PIL import Image,ImageOps,ImageDraw,ImageFont
import json,hashlib,html,base64,io
root=Path(__file__).resolve().parents[1]/'images';data=json.loads((root/'candidates/capture-data.json').read_text());frames=data['frames']
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',22)
small=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',17)
for start in [0,9]:
 sheet=Image.new('RGB',(1800,1290),'#101623');d=ImageDraw.Draw(sheet)
 for j,frame in enumerate(frames[start:start+9]):
  im=Image.open(root/'candidates'/frame['file']).convert('RGB');im.thumbnail((580,348),Image.Resampling.LANCZOS)
  x=(j%3)*600+10;y=(j//3)*430+10
  sheet.paste(im,(x+(580-im.width)//2,y+(348-im.height)//2))
  d.text((x+8,y+355),frame['id'],font=font,fill='#f5dfb8')
  title=frame['title'];d.text((x+8,y+386),title[:52],font=small,fill='#c1ccd9')
 sheet.save(root/f'contact-sheet-{1+start//9}.jpg',quality=94,subsampling=0)
checks=[]
for f in frames:
 p=root/'candidates'/f['file'];im=Image.open(p);w,h=im.size
 row={**f,'width':w,'height':h,'bytes':p.stat().st_size,'mode':im.mode,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 assert im.mode=='RGB' and p.stat().st_size<=5_000_000 and w*h<=15_000_000
 checks.append(row)
assert len(checks)==18 and sum(f['height']>f['width'] for f in checks)>=1
(root/'candidates/manifest.json').write_text(json.dumps({'source':data['source'],'images':checks,'validation':{'count':18,'portrait':sum(f['height']>f['width'] for f in checks),'all_rgb':True,'max_bytes':max(f['bytes'] for f in checks),'max_pixels':max(f['width']*f['height'] for f in checks),'page_errors':data['errors']}},indent=2)+'\n')
print(json.dumps({'count':18,'portraits':sum(f['height']>f['width'] for f in checks),'max_bytes':max(f['bytes'] for f in checks),'max_pixels':max(f['width']*f['height'] for f in checks),'page_errors':data['errors']}))

# A self-contained review gallery: embedded previews work without a server.
# Full-resolution JPEGs remain separate upload originals.
previews=[]
for f in checks:
 im=Image.open(root/'candidates'/f['file']).convert('RGB');im.thumbnail((600,600),Image.Resampling.LANCZOS)
 buf=io.BytesIO();im.save(buf,format='JPEG',quality=78,subsampling=2)
 previews.append({'id':f['id'],'title':f['title'],'file':'candidates/'+f['file'],'width':f['width'],'height':f['height'],'src':'data:image/jpeg;base64,'+base64.b64encode(buf.getvalue()).decode()})
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Night Crossing — 18 image candidates</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101623;color:#e5eaf1;font:15px/1.6 system-ui,sans-serif}header,main{max-width:1440px;margin:auto;padding:28px}h1{font:38px Georgia,serif;color:#f5dfb8;margin:0 0 8px}p{max-width:900px;color:#bcc8d8}#grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}article{background:#1a2231;border:1px solid #344257;border-radius:8px;overflow:hidden}button{font:inherit;cursor:pointer;border:0;color:inherit;background:transparent}.photo{display:block;width:100%;padding:0;height:270px;background:#090d16}.photo img{width:100%;height:100%;object-fit:contain}article section{padding:16px}h2{font-size:16px;line-height:1.4;margin:0 0 9px;color:#f5dfb8}label{display:flex;gap:10px;align-items:center}input{width:18px;height:18px;accent-color:#e8be78}.bar{position:sticky;top:0;z-index:2;background:#101623ed;border-bottom:1px solid #344257;padding:14px 28px;backdrop-filter:blur(12px)}#chosen{font-family:monospace;color:#f5dfb8}dialog{border:1px solid #52637b;background:#101623;color:#e5eaf1;width:min(1400px,96vw);max-height:96vh;padding:20px}dialog::backdrop{background:#000c}dialog img{display:block;max-width:100%;max-height:76vh;margin:auto}dialog button{padding:8px 14px;background:#28354a;border-radius:4px}#detailTitle{font-size:17px;margin:12px 0}a{color:#e9c58b}@media(max-width:960px){#grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){header,main{padding:18px}#grid{grid-template-columns:1fr}h1{font-size:30px}}</style><header><h1>Night Crossing</h1><p>18 submission image candidates. Click an image to inspect it. Tick the candidates you want to keep; your selection stays in this browser. These embedded images are review previews. The full-size JPEG originals are in the candidates folder.</p><p>Review draft · source 41d8e91 · 15 landscape / 3 portrait · no editorial captions on upload originals</p></header><div class="bar">Selected <b id="count">0</b>: <span id="chosen">None yet</span></div><main id="grid"></main><dialog id="detail"><button id="close">Close</button><h2 id="detailTitle"></h2><img id="large" alt=""><p id="dimensions"></p><a id="original" download>Download original JPEG (included with the complete folder)</a></dialog><script>const frames=__FRAMES__;const selected=new Set();try{for(const x of JSON.parse(localStorage.getItem(\'night-crossing-image-selection\')||\'[]\'))selected.add(x)}catch{}const grid=document.querySelector(\'#grid\');function summary(){document.querySelector(\'#count\').textContent=selected.size;document.querySelector(\'#chosen\').textContent=[...selected].sort().join(\', \')||\'None yet\';try{localStorage.setItem(\'night-crossing-image-selection\',JSON.stringify([...selected]))}catch{}}for(const f of frames){const article=document.createElement(\'article\');const photo=document.createElement(\'button\');photo.className=\'photo\';photo.title=\'Inspect \'+f.id;const image=new Image();image.src=f.src;image.alt=f.title;photo.append(image);photo.onclick=()=>{document.querySelector(\'#large\').src=f.src;document.querySelector(\'#large\').alt=f.title;document.querySelector(\'#detailTitle\').textContent=f.id+\' · \'+f.title;document.querySelector(\'#dimensions\').textContent=f.width+\' × \'+f.height+\' px original\';document.querySelector(\'#original\').href=f.file;document.querySelector(\'#detail\').showModal()};const section=document.createElement(\'section\');const title=document.createElement(\'h2\');title.textContent=f.id+\' · \'+f.title;const label=document.createElement(\'label\');const tick=document.createElement(\'input\');tick.type=\'checkbox\';tick.checked=selected.has(f.id);tick.onchange=()=>{tick.checked?selected.add(f.id):selected.delete(f.id);summary()};label.append(tick,\'Keep this candidate\');section.append(title,label);article.append(photo,section);grid.append(article)}document.querySelector(\'#close\').onclick=()=>document.querySelector(\'#detail\').close();summary();</script></html>'
(root/'review.html').write_text(page.replace('__FRAMES__',json.dumps(previews,separators=(',',':'))))
manifest="# Current image candidates — Night Crossing\n\nSource main `41d8e91e607775152d59d7cf0a8ab0e4a6c105bf`. This replaces the old seven-image upload recommendation. The old root-level JPEGs are historical 2D captures; use the 18 files in `candidates/` for this review.\n\nOpen [review.html](review.html) for an interactive, self-contained preview gallery, or inspect the two contact sheets. Those review aids have labels outside their thumbnails and are **not** portal upload images. Gallery previews are resized; full-size originals are separate JPEGs.\n\n## Provenance\n\nCaptured from the actual current three.js rooms in English. No generated scenery, device mockup, colour grading, retouching, scene-geometry change or editorial caption was added to an original. Capture is cropped to the actual game stage using the browser's screenshot operation. Native game UI remains visible. The guide is dismissed through Explore the ship. Transient narration is cleared through the caption module before taking each still; this is a presentation choice, not a different gameplay state.\n\nMature plants, radio settings, star lines and docked ships are staged using valid save-state fixtures. The window fog and drawing, assembly and offering/letting go use the actual game actions. A post-handover timestamp is advanced to show the lamp after placement. This is a candidate-image shoot, not evidence that one player reached every frame in one continuous playthrough. Per-frame state and recipes are recorded in `candidates/capture-data.json` and `candidates/manifest.json`.\n\nThe capture machine uses software WebGL; the game's normal adaptive resolution may lower the rendered scene resolution. The screenshots include that actual output; no detail has been invented or sharpened afterwards. These are initial candidates for owner review.\n\n## Validation\n\n18 RGB JPEGs; 15 landscape and 3 portrait. Each is below 5 MB and 15 megapixels. The final portal selection must be 4–7 images and include at least one portrait. No final sequence has been chosen.\n\n## Candidate inventory\n\n| ID | Scene / purpose | Dimensions | Bytes | Staging / action |\n|---|---|---:|---:|---|\n"
for f in checks:manifest+=f"| [{f['id']}](candidates/{f['file']}) | {f['title']} | {f['width']} × {f['height']} | {f['bytes']:,} | {f['recipe']} |\n"
manifest+='\n## First-pass selection guidance\n\n01 and 05 are the strongest starting points for the first gallery image. 07 → 08 → 14 → 15 tells the delivery story; a final selection can omit 08 if that leaves too many images. 02 and 03 are a before/after pair and should stay together if that interaction is the focus. 09, 10 and 11 provide alternate room activities. 12 shows a visible constellation; 13 is a quieter sky composition. Choose at least one of 16–18 for the portrait slot. These are editorial suggestions for review, not a final upload order.\n\n## Reproduction\n\nFrom the repository root, install project dependencies. Install Playwright separately as a capture-only tool and supply its module path in `PLAYWRIGHT_MODULE` when it is not locally resolvable. Supply a compatible Chromium executable in `CHROME`.\n\n```sh\nCHROME=/path/to/chromium PLAYWRIGHT_MODULE=/path/to/playwright/index.mjs node submission/capture/capture-candidates.mjs\npython3 submission/capture/build-review.py\n```\n\nThe builder needs Pillow. It validates originals and regenerates the contact sheets, embedded preview gallery and machine-readable manifest. No capture dependency was added to the game package.\n\nRequirements: official [2027 Registration Guide](https://assets.ctfassets.net/9el74s703hin/3LisaU32dIdDzCjhL4V8r2/9c007f552f1cbbfa1dc9ecaea88b84a5/iF_DESIGN_AWARD_2027_-_Registration_Guide_-_English.pdf), checked 4 November 2026.\n'
(root/'manifest.md').write_text(manifest)
